#include "chess.h"
#include <algorithm>
#include <sstream>
#include <stdexcept>
#include <cctype>
namespace retro {
static const std::string Types=" PNBRQK";
std::string squareName(int s){return {char('a'+(s&7)),char('1'+(s>>4))};}
int squareIndex(const std::string& s){return s.size()==2&&s[0]>='a'&&s[0]<='h'&&s[1]>='1'&&s[1]<='8'?s[0]-'a'+16*(s[1]-'1'):-1;}
std::string uci(const Move& m){return m.valid()?squareName(m.from)+squareName(m.to)+(m.promotion?std::string(1,char(std::tolower(Types[m.promotion]))):""):"0000";}
void Chess::load(const std::string& fen){std::istringstream in(fen);std::string placement,side,rights,enPassant;int h=0,f=1;if(!(in>>placement>>side>>rights>>enPassant))throw std::invalid_argument("Invalid FEN");in>>h>>f;board.fill(0);int r=7,c=0,kings[2]={0,0};for(char x:placement){if(x=='/'){if(c!=8||r<=0)throw std::invalid_argument("Invalid FEN rank");--r;c=0;}else if(x>='1'&&x<='8'){c+=x-'0';if(c>8)throw std::invalid_argument("Invalid FEN width");}else{auto pos=std::string("pnbrqk").find(char(std::tolower(x)));if(pos==std::string::npos||r<0||c>=8)throw std::invalid_argument("Invalid FEN piece");int p=int(pos)+1;if(std::islower(x))p=-p;board[r*16+c++]=p;if(std::abs(p)==6)kings[p>0?0:1]++;}}if(r!=0||c!=8||kings[0]!=1||kings[1]!=1||(side!="w"&&side!="b"))throw std::invalid_argument("Invalid FEN kings or side");turn=side=="w"?1:-1;castle=0;for(auto [x,b]:std::array<std::pair<char,int>,4>{{{'K',1},{'Q',2},{'k',4},{'q',8}}})if(rights.find(x)!=std::string::npos)castle|=b;ep=enPassant=="-"?-1:squareIndex(enPassant);if(enPassant!="-"&&(ep<0||((ep>>4)!=2&&(ep>>4)!=5)))throw std::invalid_argument("Invalid FEN en passant");half=std::max(0,h);full=std::max(1,f);}
std::string Chess::fen()const{std::string s;for(int r=7;r>=0;--r){int n=0;for(int c=0;c<8;++c){int p=board[r*16+c];if(!p)++n;else{if(n){s+=char('0'+n);n=0;}s+=p>0?Types[p]:char(std::tolower(Types[-p]));}}if(n)s+=char('0'+n);if(r)s+='/';}s+=turn==1?" w ":" b ";std::string rights;for(auto [x,b]:std::array<std::pair<char,int>,4>{{{'K',1},{'Q',2},{'k',4},{'q',8}}})if(castle&b)rights+=x;s+=(rights.empty()?"-":rights)+" "+(ep<0?"-":squareName(ep))+" "+std::to_string(half)+" "+std::to_string(full);return s;}
uint64_t Chess::key(){// FNV-1a over canonical position; ignore an unusable en-passant target.
 int effectiveEp=ep;if(ep>=0){bool available=false;for(int d:{-1,1}){int from=ep-turn*16+d;if(!(from&0x88)&&board[from]==turn&&board[ep-turn*16]==-turn){Move m{from,ep,0,true,false};int c=turn;Undo u=make(m);available=!inCheck(c);unmake(m,u);if(available)break;}}if(!available)effectiveEp=-1;}
 uint64_t hash=14695981039346656037ULL;for(int s=0;s<128;++s){if(s&0x88){s+=7;continue;}hash^=uint64_t(board[s]+6);hash*=1099511628211ULL;}for(int x:{turn+1,castle,effectiveEp+1}){hash^=uint64_t(x);hash*=1099511628211ULL;}return hash;
}
int Chess::king(int color)const{for(int s=0;s<128;++s){if(s&0x88){s+=7;continue;}if(board[s]==6*color)return s;}return -1;}
bool Chess::attacked(int s,int color)const{for(int d:{15,17}){int p=s-color*d;if(!(p&0x88)&&board[p]==color)return true;}for(int d:{33,31,18,14,-14,-18,-31,-33}){int p=s+d;if(!(p&0x88)&&board[p]==2*color)return true;}for(int d:{1,-1,16,-16,15,-15,17,-17}){int p=s+d,step=1;while(!(p&0x88)){int pc=board[p];if(pc){int t=std::abs(pc);if(pc*color>0&&(t==5||(step==1&&t==6)||(t==4&&(d==1||d==-1||d==16||d==-16))||(t==3&&(d==15||d==-15||d==17||d==-17))))return true;break;}p+=d;++step;}}return false;}
bool Chess::inCheck(int color)const{if(!color)color=turn;int k=king(color);return k<0||attacked(k,-color);}
std::vector<Move> Chess::pseudo(bool capturesOnly)const{std::vector<Move> moves;moves.reserve(64);int color=turn;auto add=[&](int from,int to,bool enPassant=false,bool castling=false){if(std::abs(board[from])==1&&((to>>4)==0||(to>>4)==7)){for(int p:{5,4,3,2})moves.push_back({from,to,p,enPassant,castling});}else moves.push_back({from,to,0,enPassant,castling});};
 for(int s=0;s<128;++s){if(s&0x88){s+=7;continue;}int p=board[s];if(p*color<=0)continue;int t=std::abs(p);if(t==1){int d=color*16,to=s+d;if(!(to&0x88)&&!board[to]){if(!capturesOnly||(to>>4)==0||(to>>4)==7)add(s,to);if(!capturesOnly&&(s>>4)==(color==1?1:6)&&!board[to+d])add(s,to+d);}for(int z:{d-1,d+1}){to=s+z;if(to&0x88)continue;if(board[to]*color<0&&std::abs(board[to])!=6)add(s,to);else if(to==ep&&board[to-d]==-color)add(s,to,true);}}else{std::vector<int> dirs=t==2?std::vector<int>{33,31,18,14,-14,-18,-31,-33}:t==3?std::vector<int>{15,-15,17,-17}:t==4?std::vector<int>{1,-1,16,-16}:std::vector<int>{1,-1,16,-16,15,-15,17,-17};for(int d:dirs){int to=s+d;while(!(to&0x88)){int target=board[to];if(target*color>0||std::abs(target)==6)break;if(!capturesOnly||target)add(s,to);if(target||t==2||t==6)break;to+=d;}}if(t==6&&!capturesOnly){int home=color==1?4:116;if(s==home&&!inCheck(color)){int kb=color==1?1:4,qb=color==1?2:8;if((castle&kb)&&board[home+3]==4*color&&!board[home+1]&&!board[home+2]&&!attacked(home+1,-color)&&!attacked(home+2,-color))add(s,home+2,false,true);if((castle&qb)&&board[home-4]==4*color&&!board[home-1]&&!board[home-2]&&!board[home-3]&&!attacked(home-1,-color)&&!attacked(home-2,-color))add(s,home-2,false,true);}}}}
 return moves;}
std::vector<Move> Chess::legal(bool capturesOnly){int color=turn;std::vector<Move> moves;for(const Move& m:pseudo(capturesOnly)){Undo u=make(m);if(!inCheck(color))moves.push_back(m);unmake(m,u);}return moves;}
Undo Chess::make(const Move& m){int p=board[m.from],c=turn;Undo u{p,board[m.to],castle,ep,half,full};board[m.from]=0;board[m.to]=m.promotion?m.promotion*c:p;if(m.ep)board[m.to-c*16]=0;if(m.castle){int rf=m.to>m.from?m.from+3:m.from-4,rt=m.to>m.from?m.from+1:m.from-1;board[rt]=board[rf];board[rf]=0;}if(std::abs(p)==6)castle&=c==1?12:3;for(auto [sq,bit]:std::array<std::pair<int,int>,4>{{{0,2},{7,1},{112,8},{119,4}}})if(m.from==sq||m.to==sq)castle&=~bit;ep=std::abs(p)==1&&std::abs(m.to-m.from)==32?(m.from+m.to)/2:-1;half=std::abs(p)==1||u.captured||m.ep?0:half+1;if(c==-1)++full;turn=-c;return u;}
void Chess::unmake(const Move& m,const Undo& u){turn=-turn;board[m.from]=u.piece;board[m.to]=u.captured;if(m.ep)board[m.to-turn*16]=-turn;if(m.castle){int rf=m.to>m.from?m.from+3:m.from-4,rt=m.to>m.from?m.from+1:m.from-1;board[rf]=board[rt];board[rt]=0;}castle=u.castle;ep=u.ep;half=u.half;full=u.full;}
bool Chess::insufficient()const{int minors=0,bishops=0,color=-1;bool same=true;for(int s=0;s<128;++s){if(s&0x88){s+=7;continue;}int t=std::abs(board[s]);if(t==1||t==4||t==5)return false;if(t==2||t==3){++minors;if(t==3){++bishops;int sc=((s>>4)+(s&7))%2;if(color<0)color=sc;else if(sc!=color)same=false;}}}return minors<2||(bishops==minors&&same);}
std::string Chess::san(const Move& m,const std::vector<Move>& list){int p=std::abs(board[m.from]);bool capture=board[m.to]||m.ep;std::string s;if(m.castle)s=m.to>m.from?"O-O":"O-O-O";else{if(p!=1){s+=Types[p];std::vector<Move> rivals;for(auto x:list)if(x.to==m.to&&x.from!=m.from&&std::abs(board[x.from])==p)rivals.push_back(x);if(!rivals.empty()){bool file=false,rank=false;for(auto x:rivals){file|=(x.from&7)==(m.from&7);rank|=(x.from>>4)==(m.from>>4);}s+=!file?squareName(m.from).substr(0,1):!rank?squareName(m.from).substr(1,1):squareName(m.from);}}else if(capture)s+=squareName(m.from)[0];if(capture)s+='x';s+=squareName(m.to);if(m.promotion){s+='=';s+=Types[m.promotion];}}Undo u=make(m);if(inCheck())s+=legal().empty()?"#":"+";unmake(m,u);return s;}
uint64_t perft(Chess& g,int d){if(!d)return 1;uint64_t n=0;for(auto m:g.legal()){Undo u=g.make(m);n+=perft(g,d-1);g.unmake(m,u);}return n;}
}
